changeSet.sql:
ALTER TABLE trigger_logs
    RENAME CONSTRAINT uq_trigger_logs_user_connector_identity_name_id
    TO uq_trigger_logs_user_connector_connection_name_id;

rollback.sql:
ALTER TABLE trigger_logs
    RENAME CONSTRAINT uq_trigger_logs_user_connector_connection_name_id
    TO uq_trigger_logs_user_connector_identity_name_id;

changeSet.comment:
channels.identity (TEXT) и channels.connection_id (UUID) держат одно значение (connections.id);
connection_id пишется при создании канала всегда. Схлопываем: бэкфилл на всякий случай,
переносим бизнес-ключ на connection_id, дропаем identity.

changeSet.sql:
CREATE UNIQUE INDEX uq_channels_agent_connector_connection_active
    ON channels (agent_id, connector_code, connection_id)
    WHERE deleted_at IS NULL;

rollback.sql:
CREATE UNIQUE INDEX uq_channels_agent_connector_identity_active
    ON channels (agent_id, connector_code, identity)
    WHERE deleted_at IS NULL;
